    RavenForgePlatforms.apply(configData);

const isCategoryVisible = (category, currentSelections) => {
        // 기존 dependsOn 체크
        if (category.dependsOn) {
          const [depKey, depVal] = Object.entries(category.dependsOn)[0];
          const currentSelection = currentSelections[depKey];
          const isVisible = Array.isArray(depVal) 
            ? depVal.includes(currentSelection) 
            : currentSelection === depVal;
          if (!isVisible) return false;
        }

        // [추가 조건] EMG TWX 또는 Fishman 선택 시 Select Coil Switch 비활성화(숨김)
        if (category.id === 'coil_switch' && (currentSelections['pickups'] === 'emg' || currentSelections['pickups'] === 'fishman' || currentSelections['electronics'] === 'fishman')) {
          return false;
        }

        return true;
      };

// 개별 옵션 표시 여부 판별
      const isOptionVisible = (categoryId, optionId, modelId, currentSelections) => {

  // 모델별 옵션 노출 제한
  const category = configData.categories.find(c => c.id === categoryId);
  const option = category?.options.find(o => o.id === optionId);
  if (!option || !RavenForgePlatforms.isInitialOption(modelId, categoryId, optionId)) return false;
  if (categoryId !== 'top_wood_selection' &&
      (option.prices?.[modelId] === undefined || option.prices[modelId] === null)) return false;

  if (
    option?.availableFor &&
    !option.availableFor.includes(modelId)
  ) {
    return false;
  }
  // 1. Hardware Bridge 룰
  if (categoryId === 'hardware_bridge') {
    if (modelId === 'EDDA') {
      const allowedEddaBridges = ['ets_custom', 'gotoh_404BO', 'hipshot_b', 'babicz_top'];
      if (!allowedEddaBridges.includes(optionId)) return false;
    }
    if (modelId === 'EMBLA') {
      if (optionId.startsWith('kahler_')) return false;
    }
    // ASKR 모델 & 멀티스케일 선택 시 특정 브릿지 4개만 허용
    if (modelId === 'ASKR' && currentSelections['scale'] === 'multi') {
      const allowedAskrMultiBridges = ['payson', 'nova_parts'];
      if (!allowedAskrMultiBridges.includes(optionId)) return false;
    }
    // payson 브릿지는 멀티스케일이 아닐 경우 무조건 숨김
    if (optionId === 'payson' && currentSelections['scale'] !== 'multi') {
      return false;
    }
    // ASKR 모델 & 35인치 스케일 선택 시 특정 브릿지 숨김
    if (modelId === 'ASKR' && currentSelections['scale'] === '35') {
      const hiddenAskr35Bridges = ['hipshot_lock', 'babicz_solo'];
      if (hiddenAskr35Bridges.includes(optionId)) return false;
    }
    
    if (optionId === 'kahler_2400' && currentSelections['scale'] === 'multi') return false;
  }

  // 2. EDDA는 3 pickup 옵션 미지원
  if (categoryId === 'pickup_configuration' && optionId === 'pickup_3' && modelId === 'EDDA') {
    return false;
  }

  // Fishman Fluence 픽업/전용 EQ 또는 Underhill 선택 시 3 pickup 옵션 자체 비노출
  if (
    categoryId === 'pickup_configuration' &&
    optionId === 'pickup_3' &&
    (
      currentSelections['pickups'] === 'fishman' ||
      currentSelections['electronics'] === 'fishman' ||
      currentSelections['electronics'] === 'underhill'
    )
  ) {
    return false;
  }

  // Both Fishman selectors remain reachable; handleOptionChange pairs the pickup and EQ.

  // Fretless has no zero fret, so the brass zero-fret guide and the retainer cannot work; verawood is reserved for fretless.
  if (categoryId === 'nut_material') {
    if (currentSelections['fret_type'] === 'fretless' && ['nut_brass', 'nut_guide'].includes(optionId)) return false;
    if (currentSelections['fret_type'] !== 'fretless' && optionId === 'nut_verawood') return false;
  }

  // 3. 3 pickup 옵션 선택 시 특정 프리앰프, 픽업 및 별도 핑거램프 제한
  if (currentSelections['pickup_configuration'] === 'pickup_3') {
    if (categoryId === 'electronics' && (optionId === 'fishman' || optionId === 'underhill')) return false;
    if (categoryId === 'pickups' && optionId === 'fishman') return false;
    
    // 3픽업 선택 시 Delano Xtender HE (delano_oval) 픽업 노출 숨김
    if (categoryId === 'pickups' && optionId === 'delano_oval') return false;

    // 3픽업에서는 가운데 픽업이 사실상 램프 역할을 하므로 별도 우드 핑거램프 비활성화
    if (categoryId === 'finger_ramp' && optionId === 'ramp_wood') return false;

  }

  return true;
};

      const normalizeSelections = (modelId, requested = {}) => {
        const fixed = RavenForgePlatforms.fixed(modelId);
        const next = { ...RavenForgePlatforms.defaults(modelId), ...requested, ...fixed };
        // Resolve dependent categories using the same available options as the UI.
        for (let pass = 0; pass < 3; pass += 1) {
          configData.categories.forEach(category => {
            if (Object.prototype.hasOwnProperty.call(fixed, category.id)) return;
            if (!isCategoryVisible(category, next)) {
              delete next[category.id];
              return;
            }
            const available = category.options.filter(option =>
              isOptionVisible(category.id, option.id, modelId, next));
            if (!available.some(option => option.id === next[category.id])) {
              const fallback = available.find(option => option.isStandard?.includes(modelId)) || available[0];
              if (fallback) next[category.id] = fallback.id;
              else delete next[category.id];
            }
          });
        }
        return { ...next, ...fixed };
      };

const applyOptionChange = (selectedModel, current, categoryId, optionId) => {
  const selections = normalizeSelections(selectedModel, current);
  if (!isOptionVisible(categoryId, optionId, selectedModel, selections)) return selections;
  const prev = selections;
    const nextSelections = { ...prev, [categoryId]: optionId };

    // [수정됨] 스케일 변경 시 브릿지 강제 조정 로직
    if (categoryId === 'scale') {
      if (optionId === 'multi') {
        if (selectedModel === 'ASKR') {
          // payson 추가
          const allowedAskrMulti = ['payson', 'nova_parts'];
          if (!allowedAskrMulti.includes(nextSelections['hardware_bridge'])) {
            nextSelections['hardware_bridge'] = RavenForgePlatforms.defaults(selectedModel).hardware_bridge;
          }
        } else if (nextSelections['hardware_bridge'] === 'kahler_2400') {
          nextSelections['hardware_bridge'] = RavenForgePlatforms.defaults(selectedModel).hardware_bridge;
        }
      } else {
        // [추가됨] 멀티스케일에서 다른 스케일로 바꿨는데 브릿지가 payson으로 남아있다면 기본값으로 리셋
        if (nextSelections['hardware_bridge'] === 'payson') {
          nextSelections['hardware_bridge'] = RavenForgePlatforms.defaults(selectedModel).hardware_bridge;
        }
      }
    }

    // Fretless 선택 시 verawood nut 자동 적용; fretted로 복귀 시 기본 brass nut으로 복귀
    if (categoryId === 'fret_type') {
      if (optionId === 'fretless') {
        nextSelections['nut_material'] = 'nut_verawood';
      } else if (nextSelections['nut_material'] === 'nut_verawood') {
        nextSelections['nut_material'] = 'nut_brass';
      }
    }

    // [Update] EMG TWX 또는 Fishman 선택 시 Select Coil Switch 숨김 및 값 초기화
    if ((categoryId === 'pickups' && (optionId === 'emg' || optionId === 'fishman')) ||
        (categoryId === 'electronics' && optionId === 'fishman')) {
      nextSelections['coil_switch'] = 'coil_none';
    }

    // [Update] 3 pickup option 선택 시 충돌 옵션 자동 정리
    if (categoryId === 'pickup_configuration' && optionId === 'pickup_3') {
      // 별도 Wood Finger Ramp는 사용할 수 없으므로 None으로 강제 전환
      nextSelections['finger_ramp'] = 'ramp_none';


      if (nextSelections['electronics'] === 'fishman' || nextSelections['electronics'] === 'underhill') {
        const elCategory = configData.categories.find(c => c.id === 'electronics');
        // 3픽업과 충돌하는 Fishman / Underhill을 제외한 사용 가능한 프리앰프로 폴백
        const fallback = elCategory.options.find(opt =>
          opt.id !== 'fishman' &&
          opt.id !== 'underhill' &&
          opt.prices[selectedModel] !== undefined &&
          opt.prices[selectedModel] !== null
        );
        if (fallback) {
          nextSelections['electronics'] = fallback.id;
        }
      }

      // [수정된 부분] fishman 뿐만 아니라 delano_oval일 때도 처리
      if (nextSelections['pickups'] === 'fishman' || nextSelections['pickups'] === 'delano_oval') {
        const puCategory = configData.categories.find(c => c.id === 'pickups');
        const fallback = puCategory.options.find(opt =>
          opt.id !== 'fishman' &&
          opt.id !== 'delano_oval' && // delano_oval도 제외하고 폴백 찾기
          opt.prices[selectedModel] !== undefined &&
          opt.prices[selectedModel] !== null
        );
        if (fallback) {
          nextSelections['pickups'] = fallback.id;
        }
      }
    }

    // Underhill Cali Dub은 2픽업 전용: 3픽업 상태에서 선택하면 2픽업으로 자동 복귀
    if (categoryId === 'electronics' && optionId === 'underhill' && nextSelections['pickup_configuration'] === 'pickup_3') {
      nextSelections['pickup_configuration'] = 'pickup_2';
    }

    // [Update] Fishman Fluence 연동 (EQ - 픽업)
    if (categoryId === 'pickups') {
      if (optionId === 'fishman') {
        nextSelections['electronics'] = 'fishman';
        nextSelections['pickup_configuration'] = 'pickup_2';
      } else if (nextSelections['electronics'] === 'fishman') {
        const elCategory = configData.categories.find(c => c.id === 'electronics');
        const fallback = elCategory.options.find(opt =>
          opt.id !== 'fishman' &&
          opt.prices[selectedModel] !== undefined &&
          opt.prices[selectedModel] !== null
        );
        if (fallback) nextSelections['electronics'] = fallback.id;
      }
    }

    if (categoryId === 'electronics') {
      if (optionId === 'fishman') {
        nextSelections['pickups'] = 'fishman';
        nextSelections['pickup_configuration'] = 'pickup_2';
      } else if (nextSelections['pickups'] === 'fishman') {
        const puCategory = configData.categories.find(c => c.id === 'pickups');
        const fallback = puCategory.options.find(opt =>
          opt.id !== 'fishman' &&
          opt.prices[selectedModel] !== undefined &&
          opt.prices[selectedModel] !== null
        );
        if (fallback) nextSelections['pickups'] = fallback.id;
      }
    }

    return normalizeSelections(selectedModel, nextSelections);
};

export { RavenForgePlatforms, configData, specialOptionsList, accessoriesList, isCategoryVisible, isOptionVisible, normalizeSelections, applyOptionChange };
